export function EncounterPolicyCard(){return <aside className="panel encounter-policy-card" aria-label="Redaktionelles politisches Anliegen"><span className="eyebrow">REDAKTIONELLE POSITION · BERGEDORF GEMEINSAM</span><h3><a href={encounterPolicyHref}>{encounterPolicyTitle}</a></h3><p>Allgemeine, generationenübergreifende Begegnungsstätten für alle: dauerhaft öffentlich finanziert, bezahlbar und ohne verpflichtende Mitgliedschaft.</p><small>Redaktioneller Stand: 13. November 2026 · Kein Beispielbeitrag und kein amtlicher Beschluss</small><p><a href={encounterPolicyHref}>Politische Forderung und Bewertungsmaßstab lesen →</a></p></aside>}
